 for(let i=0;i<310;i++){const x=45+r()*515,y=75+r()*245;box(c,x,y,2+r()*8,1+r()*3,['#2a594f','#233b36','#3b7d4f'][i%3]);}
 poly(c,[[98,150],[113,138],[504,169],[510,184],[300,245],[293,300],[274,301],[278,241]],'#52333f');poly(c,[[274,226],[182,254],[180,269],[290,247]],'#52333f');for(let i=0;i<80;i++)box(c,114+r()*370,164+r()*21,5,2,'#8f4d57');
 for(let i=0;i<33;i++){const x=30+i*17,y=50+r()*22;rock(c,x,y,14+r()*12,['#1d2235','#454a6a','#686f99']);}for(let i=0;i<11;i++){const x=i%2?560:35,y=90+Math.floor(i/2)*35;rock(c,x,y,17,['#1d2235','#454a6a','#686f99']);}
 // Forge: roof, stone chimney, glowing furnace, anvil, workbench.
