 // The branching tree anchors the permanent skill graph.
 ellipse(c,325,145,63,17,'#1a1516');poly(c,[[317,143],[320,92],[304,78],[298,51],[309,61],[329,84],[340,64],[353,55],[345,82],[333,99],[337,145]],'#bd6a62');poly(c,[[318,142],[320,103],[326,91],[327,144]],'#ffce91');for(const [x,y,w,h]of [[296,61,42,25],[329,44,43,26],[357,68,35,25],[322,79,53,20],[277,84,28,19]]){ellipse(c,x,y,w,h,'#2a594f');ellipse(c,x,y-5,w*.84,h*.85,'#3b7d4f');ellipse(c,x-4,y-12,w*.55,h*.5,'#63ab3f');}for(let i=0;i<28;i++){const x=275+r()*100,y=40+r()*54;box(c,x,y,3,3,i%3?'#92e8c0':'#ffee83');}gem(c,325,132,12,'#92e8c0','#368782');
