 ellipse(c,425,269,53,13,'#1a1516');poly(c,[[381,263],[417,212],[467,262]],'#e67839');poly(c,[[417,212],[467,262],[442,267]],'#bd6a62');poly(c,[[399,264],[417,229],[435,265]],'#451d42');box(c,412,249,12,16,'#1a1516');box(c,377,263,94,4,'#52333f');
 for(const [x,y]of [[90,223],[107,229],[478,231],[494,240]]){box(c,x,y,16,14,'#8f4d57');box(c,x+2,y+2,12,10,'#bd6a62');box(c,x+7,y,2,14,'#52333f');}
 for(const [x,y]of [[86,170],[218,183],[418,164],[527,209]]){box(c,x,y-19,3,24,'#52333f');box(c,x-3,y-25,9,9,'#ffce91');box(c,x-1,y-24,5,7,'#ffee83');}
